//! ↩️ move-scene leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfScene;
use crate::artifacts::gltf::schema::mutations::move_scene::mutation::{validate, GltfMoveScenePayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{scenes_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.move-scene.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfMoveSceneInverseOperation { Insert { position: usize, item: GltfScene }, Delete { index: usize, removed: GltfScene }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfMoveSceneInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfMoveScenePayload, pub operation: GltfMoveSceneInverseOperation }
fn operation(payload: &GltfMoveScenePayload, base: &GltfSnapshot) -> GltfMoveSceneInverseOperation { GltfMoveSceneInverseOperation::Move { index: payload.position, position: payload.index } }
fn touched_paths(payload: &GltfMoveScenePayload) -> Vec<String> { vec![format!("document/scenes/{}", payload.index), format!("document/scenes/{}", payload.position)] }
pub fn validate_inverse(inverse: &GltfMoveSceneInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfMoveSceneInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfMoveSceneInverseOperation::Insert { position, .. } if *position > after.document.scenes.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/scenes", "position must be within the collection")), GltfMoveSceneInverseOperation::Delete { index, .. } if *index >= after.document.scenes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/scenes", "index must address an item")), GltfMoveSceneInverseOperation::Move { index, position } if *index >= after.document.scenes.len() || *position >= after.document.scenes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/scenes", "indices must address items")), GltfMoveSceneInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.scenes.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.scenes.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/scenes", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfMoveSceneInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Scenes, &Change::Insert(*position))?; next.document.scenes.insert(*position, item.clone());  }, GltfMoveSceneInverseOperation::Delete { index, .. } => { scenes_op(&mut next, GltfTopLevelFamily::Scenes, *index, None, None)?;  }, GltfMoveSceneInverseOperation::Move { index, position } => { scenes_op(&mut next, GltfTopLevelFamily::Scenes, *index, Some(*position), None)?;  }, GltfMoveSceneInverseOperation::Reorder { order } => { scenes_op(&mut next, GltfTopLevelFamily::Scenes, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfMoveSceneInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfMoveScenePayload, base: &GltfSnapshot) -> Result<GltfMoveSceneInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfMoveSceneInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
